def merge_intervals(intervals):
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = []
    cs, ce = ivs[0][0], ivs[0][1]
    for iv in ivs[1:]:
        s, e = iv[0], iv[1]
        if s <= ce:
            if e > ce:
                ce = e
        else:
            merged.append([cs, ce])
            cs, ce = s, e
    merged.append([cs, ce])
    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)
    indegree = {node: 0 for node in nodes}
    adjacency = {node: [] for node in nodes}

    for source, destination in unique_edges:
        adjacency[source].append(destination)
        indegree[destination] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(heap, destination)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError("limit must be a positive integer")

    batches = []
    current = []
    total = 0

    for name, weight in items:
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0 or weight > limit:
            raise ValueError("weight must be an integer between 1 and limit")

        if total + weight > limit:
            batches.append(current)
            current = [name]
            total = weight
        else:
            current.append(name)
            total += weight

    if current:
        batches.append(current)

    return batches

import re

def parse_env(text):
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError("missing =")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
            raise ValueError("invalid key: %r" % key)
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    text = b''.join(chunks).decode('utf-8')
    events = []
    pending = []
    i = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j] != '\n' and text[j] != '\r':
            j += 1
        line = text[i:j]
        if j < n:
            if text[j] == '\r' and text[j + 1:j + 2] == '\n':
                end = j + 2
            else:
                end = j + 1
        else:
            end = j
        if line == '':
            if pending:
                value = '\n'.join(pending)
                if value == '[DONE]':
                    return events
                events.append(value)
            pending = []
        else:
            if not line.startswith(':'):
                colon = line.find(':')
                if colon == -1:
                    name = line
                    value = ''
                else:
                    name = line[:colon]
                    value = line[colon + 1:]
                    if value.startswith(' '):
                        value = value[1:]
                if name == 'data':
                    pending.append(value)
        i = end
    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    base = float(base)
    cap = float(cap)
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")
    if not (math.isfinite(base) and math.isfinite(cap)):
        raise ValueError("base and cap must be finite")
    if base == 0.0 or cap == 0.0:
        return 0.0

    m_base, e_base = math.frexp(base)
    m_cap, e_cap = math.frexp(cap)
    delta = e_base + attempt - e_cap

    if delta >= 1:
        return cap
    if delta == 0 and m_base >= m_cap:
        return cap

    return float(cap * (m_base / m_cap) * (2.0 ** delta))

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds budget")

    admitted = []
    remaining_tokens = budget - sum(active)
    remaining_slots = slots - len(active)

    index = 0
    for reservation in queued:
        if reservation <= remaining_tokens and remaining_slots > 0:
            admitted.append(reservation)
            remaining_tokens -= reservation
            remaining_slots -= 1
            index += 1
        else:
            break

    remaining = list(queued[index:])
    return admitted, remaining
